# ruff: noqa: E501

from fastapi import APIRouter
from fastapi.responses import HTMLResponse

router = APIRouter(include_in_schema=False)


@router.get("/map", response_class=HTMLResponse)
async def map_awareness_page() -> HTMLResponse:
    return HTMLResponse(
        """<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <title>RoadTalk | Map Awareness</title>
  <style>
    :root{color-scheme:dark;--bg:#07141b;--panel:#10232e;--panel2:#0b1c25;--text:#f2f7f9;--muted:#8fa7b2;--accent:#f2b84b;--green:#70da96;--red:#ff7979;--line:rgba(255,255,255,.1)}
    *{box-sizing:border-box}body{margin:0;background:radial-gradient(circle at 18% 0,rgba(242,184,75,.12),transparent 34rem),var(--bg);color:var(--text);font-family:Inter,system-ui,sans-serif;min-height:100vh}.wrap{width:min(1180px,calc(100% - 28px));margin:auto}header{border-bottom:1px solid var(--line);background:rgba(7,20,27,.86);backdrop-filter:blur(14px);position:sticky;top:0;z-index:5}nav{min-height:68px;display:flex;align-items:center;justify-content:space-between;gap:16px}.brand{display:flex;align-items:center;gap:12px;font-weight:850}.mark{width:42px;height:42px;border-radius:14px;background:var(--accent);color:#172028;display:grid;place-items:center;font-weight:950}.navlinks{display:flex;gap:8px;flex-wrap:wrap}a.button,button{font:inherit;border:1px solid var(--line);background:rgba(255,255,255,.04);color:var(--text);text-decoration:none;padding:9px 12px;border-radius:10px;cursor:pointer}.active{border-color:var(--accent)!important}main{padding:30px 0 64px}.hero{display:flex;justify-content:space-between;align-items:end;gap:18px;margin-bottom:18px}.eyebrow{color:var(--accent);font-size:11px;font-weight:900;letter-spacing:.16em;text-transform:uppercase}h1{font-size:clamp(30px,5vw,48px);letter-spacing:-.04em;margin:7px 0}.subtitle,.muted{color:var(--muted)}.layout{display:grid;grid-template-columns:1.5fr .5fr;gap:16px}.card{border:1px solid var(--line);background:linear-gradient(180deg,rgba(16,35,46,.96),rgba(11,28,37,.94));border-radius:20px;box-shadow:0 22px 70px rgba(0,0,0,.2)}.map-card{padding:16px}.map{height:min(65vh,620px);min-height:420px;border:1px solid var(--line);border-radius:15px;overflow:hidden;position:relative;background:#0a2028}.map-grid{position:absolute;inset:0;background-image:linear-gradient(rgba(255,255,255,.045) 1px,transparent 1px),linear-gradient(90deg,rgba(255,255,255,.045) 1px,transparent 1px);background-size:48px 48px}.map::after{content:'Local awareness canvas · no public map or tile provider';position:absolute;left:14px;bottom:12px;color:var(--muted);font-size:11px;background:rgba(7,20,27,.8);padding:6px 8px;border-radius:8px}.you{position:absolute;left:50%;top:50%;width:18px;height:18px;border:4px solid white;background:var(--accent);border-radius:50%;transform:translate(-50%,-50%);box-shadow:0 0 0 8px rgba(242,184,75,.15)}.you::after{content:'You';position:absolute;left:22px;top:-4px;font-size:12px;font-weight:800;white-space:nowrap}.cell{position:absolute;width:70px;height:70px;border-radius:20px;border:2px solid rgba(112,218,150,.72);background:rgba(112,218,150,.12);display:grid;place-items:center;font-size:11px;font-weight:850;color:var(--green);transform:translate(-50%,-50%)}.side{display:grid;gap:16px}.panel{padding:19px}.panel h2{font-size:16px;margin:0 0 13px}.status{display:flex;gap:9px;align-items:flex-start;padding:11px 0;border-bottom:1px solid var(--line)}.status:last-child{border-bottom:0}.dot{width:9px;height:9px;border-radius:50%;background:var(--accent);margin-top:5px;flex:0 0 auto}.dot.ok{background:var(--green)}.dot.bad{background:var(--red)}.status strong{display:block}.status small{display:block;color:var(--muted);margin-top:3px;line-height:1.45}.privacy{font-size:12px;color:var(--muted);line-height:1.55}.privacy strong{color:var(--text)}.refresh{width:100%;background:var(--accent);color:#172028;border:0;font-weight:900;padding:12px}.empty{position:absolute;inset:0;display:grid;place-items:center;text-align:center;color:var(--muted);padding:30px;pointer-events:none}.empty[hidden]{display:none}.diagnostic{color:var(--red);font-size:12px;line-height:1.5;margin-top:12px}.legend{display:flex;gap:14px;flex-wrap:wrap;color:var(--muted);font-size:11px;margin-top:11px}.swatch{display:inline-block;width:10px;height:10px;border-radius:3px;background:rgba(112,218,150,.25);border:1px solid var(--green);margin-right:5px}.own{border-radius:50%;background:var(--accent);border-color:white}
    @media(max-width:850px){.layout{grid-template-columns:1fr}.hero{align-items:flex-start;flex-direction:column}.map{height:52vh}}@media(max-width:560px){nav{padding:12px 0;align-items:flex-start;flex-direction:column}.map{min-height:360px}.navlinks{width:100%}}
  </style>
</head>
<body>
<header><div class="wrap"><nav><div class="brand"><div class="mark">RT</div><div>RoadTalk <span class="muted">Map Awareness</span></div></div><div class="navlinks"><a class="button" href="/">Web Radio</a><a class="button active" href="/map" aria-current="page">Map</a><a class="button" href="/audience">Audience</a><a class="button" href="/ops">Operations</a></div></nav></div></header>
<main class="wrap">
  <section class="hero"><div><div class="eyebrow">Privacy-safe awareness</div><h1>See the road around you.</h1><p class="subtitle">Your browser can orient your own position. Other RoadTalk users appear only as coarse, privacy-thresholded areas.</p></div><button id="refresh" class="refresh" type="button">Refresh awareness</button></section>
  <section class="layout">
    <article class="card map-card"><div id="map" class="map" role="img" aria-label="RoadTalk awareness map"><div class="map-grid"></div><div id="you" class="you" hidden></div><div id="empty" class="empty">Waiting for foreground location and nearby presence.</div></div><div class="legend"><span><i class="swatch own"></i>Your current browser position</span><span><i class="swatch"></i>Coarse area with at least 3 RoadTalk accounts</span></div></article>
    <aside class="side">
      <article class="card panel" aria-live="polite"><h2>Awareness status</h2><div class="status"><span id="secure-dot" class="dot"></span><div><strong id="secure-state">Checking browser</strong><small id="secure-detail">Secure context is required for foreground location.</small></div></div><div class="status"><span id="location-dot" class="dot"></span><div><strong id="location-state">Location not checked</strong><small id="location-detail">RoadTalk requests location only while this page is active and you refresh awareness.</small></div></div><div class="status"><span id="presence-dot" class="dot"></span><div><strong id="presence-state">Presence not loaded</strong><small id="presence-detail">Other users are shown only after the privacy threshold is met.</small></div></div><div id="diagnostic" class="diagnostic"></div></article>
      <article class="card panel"><h2>Privacy boundary</h2><p class="privacy"><strong>Your marker:</strong> uses the position this browser just accepted. It is not sent to any map or tile provider.</p><p class="privacy"><strong>Other users:</strong> only approved 2 km coarse cells are rendered. No identity, exact count, exact coordinate, distance, bearing, heading, speed, route, destination, or history is available to this page.</p><p class="privacy"><strong>Map background:</strong> this Sprint uses a deterministic local canvas. No public map, tile, geocoding, routing, or traffic service is contacted.</p></article>
    </aside>
  </section>
</main>
<script>
const state={access:null,refresh:null,position:null};
const $=id=>document.getElementById(id);
const forbidden=['account_id','device_id','identity','callsign','exact_count','distance','distance_m','bearing','heading','speed','route','corridor','direction','destination','history'];
function setStatus(prefix,title,detail,kind=''){$(prefix+'-state').textContent=title;$(prefix+'-detail').textContent=detail;$(prefix+'-dot').className='dot '+kind}
function authHeaders(){return state.access?{Authorization:`Bearer ${state.access}`}:{}}
async function refreshToken(){if(!state.refresh)return false;const r=await fetch('/api/v1/auth/refresh',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({refresh_token:state.refresh})});if(!r.ok)return false;const b=await r.json();state.access=b.access_token;state.refresh=b.refresh_token;localStorage.setItem('rt_access',state.access);localStorage.setItem('rt_refresh',state.refresh);return true}
async function raw(path){return fetch(path,{headers:{Accept:'application/json',...authHeaders()}})}
async function api(path){let r=await raw(path);if(r.status===401&&await refreshToken())r=await raw(path);if(!r.ok)throw new Error(`HTTP ${r.status}`);return r.json()}
async function ensureSession(){state.access=localStorage.getItem('rt_access');state.refresh=localStorage.getItem('rt_refresh');if(state.access){try{await api('/api/v1/auth/session');return}catch{}}const install=localStorage.getItem('rt_install')||`web-${crypto.randomUUID()}`;localStorage.setItem('rt_install',install);const r=await fetch('/api/v1/auth/anonymous',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({installation_id:install,platform:'web'})});if(!r.ok)throw new Error('Browser session unavailable');const b=await r.json();state.access=b.access_token;state.refresh=b.refresh_token;localStorage.setItem('rt_access',state.access);localStorage.setItem('rt_refresh',state.refresh)}
function position(){return new Promise((resolve,reject)=>navigator.geolocation.getCurrentPosition(resolve,reject,{enableHighAccuracy:true,maximumAge:5000,timeout:10000}))}
function validatePresence(data){const encoded=JSON.stringify(data).toLowerCase();for(const key of forbidden)if(encoded.includes(`\"${key}\"`))throw new Error('Presence response crossed the browser privacy boundary');if(data.policy_version!=='presence-v1'||data.privacy_min_accounts!==3||!Array.isArray(data.cells))throw new Error('Presence policy mismatch');for(const cell of data.cells){if(cell.cell_size_m!==2000||!['few','several','many'].includes(cell.density))throw new Error('Invalid coarse presence cell')}return data}
function projectCell(cell){if(!state.position)return null;const ownLat=state.position.coords.latitude;const ownLon=state.position.coords.longitude;const cos=Math.max(.2,Math.cos(ownLat*Math.PI/180));const east=(cell.approximate_longitude-ownLon)*111320*cos;const north=(cell.approximate_latitude-ownLat)*111320;const scale=12000;return{x:50+(east/scale)*50,y:50-(north/scale)*50}}
function render(data){document.querySelectorAll('.cell').forEach(e=>e.remove());let visible=0;for(const cell of data.cells){const p=projectCell(cell);if(!p||p.x<4||p.x>96||p.y<4||p.y>96)continue;const el=document.createElement('div');el.className='cell';el.style.left=p.x+'%';el.style.top=p.y+'%';el.textContent=cell.density;el.setAttribute('aria-label',`Coarse presence area, density ${cell.density}`);$('map').appendChild(el);visible++}$('empty').hidden=Boolean(state.position||visible);setStatus('presence',data.cells.length?`${data.cells.length} coarse area${data.cells.length===1?'':'s'} available`:'No visible presence areas',data.cells.length?'Only privacy-thresholded 2 km areas are displayed.':'Sparse or unavailable populations remain hidden.','ok')}
async function refreshAwareness(){const button=$('refresh');button.disabled=true;$('diagnostic').textContent='';try{if(!window.isSecureContext)throw new Error('Browser location requires a secure origin. Use http://127.0.0.1 on this computer or the RoadTalk HTTPS LAN gateway.');if(!navigator.geolocation)throw new Error('This browser does not provide foreground location access.');setStatus('secure','Secure browser context','Foreground location capability is available.','ok');try{state.position=await position();$('you').hidden=false;setStatus('location','Foreground location active',`Browser accuracy about ${Math.round(state.position.coords.accuracy)} m. Your exact position is shown only to you on this page.`,'ok')}catch(error){setStatus('location','Location unavailable','Allow location for this site and enable the operating-system location service.','bad');throw error}await ensureSession();const data=validatePresence(await api('/api/v1/presence/nearby'));render(data)}catch(error){$('diagnostic').textContent=error&&error.message?error.message:String(error);if(!state.position)setStatus('presence','Presence degraded','RoadTalk cannot orient awareness until foreground location is available.','bad')}finally{button.disabled=false}}
$('refresh').addEventListener('click',()=>void refreshAwareness());if(!window.isSecureContext){setStatus('secure','Secure context required','Use http://127.0.0.1 locally or the RoadTalk HTTPS LAN gateway.','bad')}else if(!navigator.geolocation){setStatus('secure','Location capability unavailable','Try a current browser with location enabled.','bad')}else{setStatus('secure','Browser ready','Press Refresh awareness to request foreground location.','ok')}
</script>
</body>
</html>"""
    )
